import React, { useState, useEffect } from 'react';
import { auth } from './firebase'; // importera din auth-instans
import {
  EmailAuthProvider,
  reauthenticateWithCredential,
  updatePassword
} from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { db } from './firebase';
import { FaCheckCircle, FaExclamationTriangle } from 'react-icons/fa'; 
import './Settings.css'; // Importera CSS

function Settings({ user }) {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmNewPassword, setConfirmNewPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [company, setCompany] = useState(null);

  // Om användaren är admin och har ett kopplat companyId, hämta företagets data
  useEffect(() => {
    if (user && user.role && user.role.toLowerCase() === 'admin' && user.companyId) {
      const fetchCompany = async () => {
        try {
          const companyRef = doc(db, 'companies', user.companyId);
          const companySnap = await getDoc(companyRef);
          if (companySnap.exists()) {
            setCompany(companySnap.data());
          }
        } catch (err) {
          console.error("Fel vid hämtning av företagsdata:", err);
        }
      };
      fetchCompany();
    }
  }, [user]);

  const handlePasswordChange = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (newPassword !== confirmNewPassword) {
      setError('Dina nya lösenord matchar inte.');
      return;
    }

    try {
      // Reautentisera användaren
      const credential = EmailAuthProvider.credential(user.email, currentPassword);
      await reauthenticateWithCredential(auth.currentUser, credential);

      // Uppdatera lösenordet
      await updatePassword(auth.currentUser, newPassword);
      setSuccess('Ditt lösenord har uppdaterats!');
      setCurrentPassword('');
      setNewPassword('');
      setConfirmNewPassword('');
    } catch (err) {
      setError('Ditt nuvarande lösenord stämmer inte eller så är det nya lösenordet för svagt.');
    }
  };

  return (
    <div className="settings-container">
      {/* Container för lösenordsändring */}
      <div className="password-settings">
        <h2>Ändra lösenord</h2>
        <form onSubmit={handlePasswordChange} className="settings-form">
          <div className="form-group">
            <label htmlFor="currentPassword">Nuvarande lösenord</label>
            <input
              type="password"
              id="currentPassword"
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="newPassword">Nytt lösenord</label>
            <input
              type="password"
              id="newPassword"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="confirmNewPassword">Bekräfta nytt lösenord</label>
            <input
              type="password"
              id="confirmNewPassword"
              value={confirmNewPassword}
              onChange={(e) => setConfirmNewPassword(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="save-button">
            Spara nytt lösenord
          </button>
        </form>
        {error && (
          <div className="settings-message error">
            <FaExclamationTriangle className="icon" />
            <span>{error}</span>
          </div>
        )}
        {success && (
          <div className="settings-message success">
            <FaCheckCircle className="icon" />
            <span>{success}</span>
          </div>
        )}
      </div>

      {/* Separat container för företagsinställningar (endast för admin) */}
      {user && user.role && user.role.toLowerCase() === 'admin' && (
        <div className="company-settings-container">
          <h2>Företag</h2>
          {company ? (
            <div className="company-info">
              <p className="company-name">
                <strong>Företag:</strong> {company.name}
              </p>
              <div className="company-logo-section">
                <p className="logo-label"><strong>Logga:</strong></p>
                {company.imageUrl ? (
                  <img
                    src={company.imageUrl}
                    alt={company.name}
                    className="company-settings-logo"
                  />
                ) : (
                  <p>Ingen logga tillgänglig.</p>
                )}
              </div>
            </div>
          ) : (
            <p>Ingen företagsdata hittad.</p>
          )}
        </div>
      )}
    </div>
  );
}

export default Settings;
