import React, { useState, useEffect } from 'react';
import { collection, getDocs, query, where } from 'firebase/firestore';
import { db } from './firebase';
import { FaChartBar, FaTimes } from 'react-icons/fa';
import './SuperAdminDashboard.css';

function SuperAdminDashboard() {
  const [companies, setCompanies] = useState([]);
  const [selectedCompany, setSelectedCompany] = useState(null);
  const [stats, setStats] = useState(null);
  const [loadingStats, setLoadingStats] = useState(false);

  // Hämta alla företag från "companies"-samlingen
  useEffect(() => {
    const fetchCompanies = async () => {
      try {
        const companiesSnapshot = await getDocs(collection(db, 'companies'));
        const companiesList = companiesSnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        setCompanies(companiesList);
      } catch (error) {
        console.error("Fel vid hämtning av företag:", error.message);
      }
    };

    fetchCompanies();
  }, []);

  // Hämtar statistik för ett specifikt företag
  const fetchStats = async (company) => {
    setLoadingStats(true);
    try {
      // Hämta antalet publicerade jobb
      const jobsQuery = query(
        collection(db, 'jobs'),
        where('companyId', '==', company.id)
      );
      const jobsSnapshot = await getDocs(jobsQuery);
      const jobsCount = jobsSnapshot.size;

      // Hämta antalet ansökningar
      const applicationsQuery = query(
        collection(db, 'applications'),
        where('companyId', '==', company.id)
      );
      const applicationsSnapshot = await getDocs(applicationsQuery);
      const applicationsCount = applicationsSnapshot.size;

      setStats({
        jobsCount,
        applicationsCount
      });
    } catch (error) {
      console.error("Fel vid hämtning av statistik:", error.message);
    }
    setLoadingStats(false);
  };

  // Öppna statistik-popup för valt företag
  const openStats = (company) => {
    setSelectedCompany(company);
    setStats(null);
    fetchStats(company);
  };

  const closeStats = () => {
    setSelectedCompany(null);
    setStats(null);
  };

  return (
    <div className="superadmin-dashboard">
      <h1>Superadmin Dashboard</h1>
      {companies.length === 0 ? (
        <p>Inga företag hittades.</p>
      ) : (
        <ul className="company-list">
          {companies.map(company => (
            <li key={company.id} className="company-item">
              <span className="company-name">{company.name}</span>
              <button
                className="stats-button"
                onClick={() => openStats(company)}
                title="Visa statistik"
              >
                <FaChartBar />
              </button>
            </li>
          ))}
        </ul>
      )}

      {/* Statistik-popup */}
      {selectedCompany && (
        <div className="popup-overlay" onClick={closeStats}>
          <div className="popup" onClick={(e) => e.stopPropagation()}>
            <div className="popup-header">
              <h2>{selectedCompany.name} – Statistik</h2>
              <button className="close-button" onClick={closeStats}>
                <FaTimes />
              </button>
            </div>
            {loadingStats ? (
              <p>Laddar statistik...</p>
            ) : stats ? (
              <div className="stats-content">
                <p>
                  <strong>Publicerade jobb:</strong> {stats.jobsCount}
                </p>
                <p>
                  <strong>Totalt antal ansökningar:</strong> {stats.applicationsCount}
                </p>
              </div>
            ) : (
              <p>Ingen statistik tillgänglig.</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default SuperAdminDashboard;
