import React, { useState, useEffect, useCallback } from 'react';
import {
  collection,
  getDocs,
  setDoc,
  deleteDoc,
  doc,
  updateDoc,
  query,
  where
} from 'firebase/firestore';
import { db } from './firebase';
import './ManageCompanies.css';

// Enkel Modal-komponent
function Modal({ children, onClose }) {
  return (
    <div className="mc-modal-overlay">
      <div className="mc-modal">
        <button className="mc-modal-close" onClick={onClose}>×</button>
        {children}
      </div>
    </div>
  );
}

function ManageCompanies() {
  const [companies, setCompanies] = useState([]);

  // States för "Lägg till företag"-formuläret
  const [newCompanyName, setNewCompanyName] = useState('');
  const [newCompanyAddress, setNewCompanyAddress] = useState('');
  const [newCompanyPhone, setNewCompanyPhone] = useState('');
  const [newCompanyImageUrl, setNewCompanyImageUrl] = useState('');
  const [newCompanyFile, setNewCompanyFile] = useState(null);

  // States för redigeringsformuläret
  const [editCompanyId, setEditCompanyId] = useState('');
  const [editCompanyName, setEditCompanyName] = useState('');
  const [editCompanyAddress, setEditCompanyAddress] = useState('');
  const [editCompanyPhone, setEditCompanyPhone] = useState('');
  const [editCompanyImageUrl, setEditCompanyImageUrl] = useState('');
  const [originalCompanyId, setOriginalCompanyId] = useState('');

  // Övriga states
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // Modal-states
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [companyToDelete, setCompanyToDelete] = useState(null);

  // Hämta företag vid sidladdning
  useEffect(() => {
    const fetchCompanies = async () => {
      try {
        const companiesSnapshot = await getDocs(collection(db, 'companies'));
        setCompanies(companiesSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
      } catch (err) {
        setError('Kunde inte hämta företagsdata.');
      }
    };
    fetchCompanies();
  }, []);

  // Funktioner för att ta bort alla dokument med ett visst companyId från olika kollektioner
  const deleteRelatedDocuments = useCallback(async (companyId) => {
    // Ta bort användare
    const usersQuery = query(collection(db, 'users'), where('companyId', '==', companyId));
    const usersSnapshot = await getDocs(usersQuery);
    for (const userDoc of usersSnapshot.docs) {
      console.log(`Försöker radera användardokument med ID: ${userDoc.id}`);
      try {
        await deleteDoc(doc(db, 'users', userDoc.id));
        console.log(`Användardokument raderat: ${userDoc.id}`);
      } catch (err) {
        console.error(`Misslyckades med att radera användardokument: ${userDoc.id}`, err);
        throw err;
      }
    }

    // Ta bort pageVisits
    const visitsQuery = query(collection(db, 'pageVisits'), where('companyId', '==', companyId));
    const visitsSnapshot = await getDocs(visitsQuery);
    for (const visitDoc of visitsSnapshot.docs) {
      console.log(`Försöker radera pageVisit med ID: ${visitDoc.id}`);
      try {
        await deleteDoc(doc(db, 'pageVisits', visitDoc.id));
        console.log(`pageVisit raderat: ${visitDoc.id}`);
      } catch (err) {
        console.error(`Misslyckades med att radera pageVisit: ${visitDoc.id}`, err);
        throw err;
      }
    }

    // Ta bort ansökningar
    const appsQuery = query(collection(db, 'applications'), where('companyId', '==', companyId));
    const appsSnapshot = await getDocs(appsQuery);
    for (const appDoc of appsSnapshot.docs) {
      console.log(`Försöker radera ansökningsdokument med ID: ${appDoc.id}`);
      try {
        await deleteDoc(doc(db, 'applications', appDoc.id));
        console.log(`Ansökningsdokument raderat: ${appDoc.id}`);
      } catch (err) {
        console.error(`Misslyckades med att radera ansökningsdokument: ${appDoc.id}`, err);
        throw err;
      }
    }

    // Ta bort jobb
    const jobsQuery = query(collection(db, 'jobs'), where('companyId', '==', companyId));
    const jobsSnapshot = await getDocs(jobsQuery);
    for (const jobDoc of jobsSnapshot.docs) {
      console.log(`Försöker radera jobb med ID: ${jobDoc.id}`);
      try {
        await deleteDoc(doc(db, 'jobs', jobDoc.id));
        console.log(`Jobb raderat: ${jobDoc.id}`);
      } catch (err) {
        console.error(`Misslyckades med att radera jobb: ${jobDoc.id}`, err);
        throw err;
      }
    }
  }, []);

  // Generera företags-ID utifrån företagsnamnet.
  const generateCompanyId = (name) => {
    return name
      .replace(/Å/g, 'A')
      .replace(/Ä/g, 'A')
      .replace(/Ö/g, 'O')
      .replace(/å/g, 'a')
      .replace(/ä/g, 'a')
      .replace(/ö/g, 'o')
      .replace(/\s+/g, '-')
      .replace(/[^A-Za-z0-9-]/g, '');
  };

  // Hantera filändring (när användaren väljer en fil)
  const handleFileChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      setNewCompanyFile(e.target.files[0]);
    }
  };

  // Funktion för att ladda upp bilden till ImgBB med din API-nyckel
  const handleUploadImgBB = async () => {
    if (!newCompanyFile) {
      setError('Vänligen välj en bildfil.');
      return;
    }
    try {
      const apiKey = 'f3260ecf4bafe55f9ed1476ab690c4c5';
      const formData = new FormData();
      formData.append('image', newCompanyFile);
      const response = await fetch(`https://api.imgbb.com/1/upload?key=${apiKey}`, {
        method: 'POST',
        body: formData,
      });
      if (!response.ok) {
        throw new Error('Uppladdning misslyckades');
      }
      const data = await response.json();
      if (data && data.data && data.data.url) {
        setNewCompanyImageUrl(data.data.url);
        setSuccess('Bild uppladdad!');
        setError('');
      } else {
        throw new Error('Ingen bild-URL mottagen');
      }
    } catch (error) {
      console.error(error);
      setError('Fel vid uppladdning av bild: ' + error.message);
    }
  };

  // Lägg till företag (används i add modal)
  const handleAddCompany = async () => {
    if (!newCompanyName || !newCompanyAddress || !newCompanyPhone || !newCompanyImageUrl) {
      setError('Fyll i företagsnamn, adress, telefon och se till att en bild URL finns.');
      return;
    }
    if (!newCompanyImageUrl && newCompanyFile) {
      await handleUploadImgBB();
    }
    if (!newCompanyImageUrl) {
      setError('Bild URL saknas, vänligen ange en bild URL eller välj en bildfil.');
      return;
    }
    try {
      const companyId = generateCompanyId(newCompanyName);
      const companyData = {
        name: newCompanyName,
        address: newCompanyAddress,
        phone: newCompanyPhone,
        imageUrl: newCompanyImageUrl,
      };
      await setDoc(doc(db, 'companies', companyId), companyData);
      setCompanies([...companies, { id: companyId, ...companyData }]);
      setSuccess('Företag tillagt!');
      setError('');
      setNewCompanyName('');
      setNewCompanyAddress('');
      setNewCompanyPhone('');
      setNewCompanyImageUrl('');
      setNewCompanyFile(null);
      setShowAddModal(false);
    } catch (err) {
      console.error(err);
      setError('Kunde inte lägga till företag.');
    }
  };

  const openDeleteModal = (company) => {
    setCompanyToDelete(company);
    setShowDeleteModal(true);
  };

  // Ta bort företag och all relaterad data
  const confirmDeleteCompany = async () => {
    if (!companyToDelete) return;
    const companyId = companyToDelete.id;
    try {
      console.log(`Startar radering av relaterade dokument för company: ${companyId}`);
      await deleteRelatedDocuments(companyId);
      console.log(`Försöker radera företagets dokument: ${companyId}`);
      await deleteDoc(doc(db, 'companies', companyId));
      console.log(`Företagets dokument raderat: ${companyId}`);
      setCompanies(companies.filter(company => company.id !== companyId));
      setSuccess('Företaget och all relaterad data har tagits bort.');
      setShowDeleteModal(false);
      setCompanyToDelete(null);
    } catch (err) {
      console.error(`Radering misslyckades för företag: ${companyId}`, err);
      setError('Kunde inte ta bort företaget och dess relaterade data.');
    }
  };

  // Öppna redigeringsmodal – visas formuläret för att redigera företagsinformation
  const handleStartEdit = (company) => {
    setOriginalCompanyId(company.id);
    setEditCompanyId(company.id);
    setEditCompanyName(company.name);
    setEditCompanyAddress(company.address);
    setEditCompanyPhone(company.phone);
    setEditCompanyImageUrl(company.imageUrl);
    setShowEditModal(true);
    setError('');
    setSuccess('');
  };

  const handleSaveEditCompany = async () => {
    if (!editCompanyId || !editCompanyName || !editCompanyAddress || !editCompanyPhone || !editCompanyImageUrl) {
      setError('Fyll i företags-ID, namn, adress, telefon och bild URL.');
      return;
    }
    try {
      const companyData = {
        name: editCompanyName,
        address: editCompanyAddress,
        phone: editCompanyPhone,
        imageUrl: editCompanyImageUrl,
      };

      if (originalCompanyId === editCompanyId) {
        await updateDoc(doc(db, 'companies', originalCompanyId), companyData);
        setCompanies(companies.map(company =>
          company.id === originalCompanyId ? { id: editCompanyId, ...companyData } : company
        ));
      } else {
        await setDoc(doc(db, 'companies', editCompanyId), companyData);
        await deleteDoc(doc(db, 'companies', originalCompanyId));
        setCompanies(companies.map(company =>
          company.id === originalCompanyId ? { id: editCompanyId, ...companyData } : company
        ));
      }
      setSuccess('Företaget har uppdaterats!');
      setError('');
      setShowEditModal(false);
      setOriginalCompanyId('');
      setEditCompanyId('');
      setEditCompanyName('');
      setEditCompanyAddress('');
      setEditCompanyPhone('');
      setEditCompanyImageUrl('');
    } catch (err) {
      console.error(err);
      setError('Kunde inte uppdatera företaget.');
    }
  };

  const handleCancelEdit = () => {
    setShowEditModal(false);
    setOriginalCompanyId('');
    setEditCompanyId('');
    setEditCompanyName('');
    setEditCompanyAddress('');
    setEditCompanyPhone('');
    setEditCompanyImageUrl('');
    setError('');
  };

  return (
    <div className="mc-manage-companies" id="mc-manage-companies">
      <h1 id="mc-title">Hantera Företag</h1>
      {error && <p className="mc-error-message" id="mc-error-message">{error}</p>}
      {success && <p className="mc-success-message" id="mc-success-message">{success}</p>}

      <div className="mc-top-buttons">
        <button className="mc-btn mc-add-btn" onClick={() => setShowAddModal(true)}>
          Lägg till nytt företag
        </button>
      </div>

      <ul className="mc-company-list" id="mc-company-list">
        {companies.map(company => (
          <li key={company.id} className="mc-company-item" id={`mc-company-item-${company.id}`}>
            <div className="mc-company-info" id={`mc-company-info-${company.id}`}>
              <img
                src={company.imageUrl}
                alt={company.name}
                className="mc-company-image"
                id={`mc-company-image-${company.id}`}
              />
              <div className="mc-company-details" id={`mc-company-details-${company.id}`}>
                <p className="mc-company-name" id={`mc-company-name-${company.id}`}>{company.name}</p>
                <p className="mc-company-address" id={`mc-company-address-${company.id}`}>{company.address}</p>
                <p className="mc-company-phone" id={`mc-company-phone-${company.id}`}>{company.phone}</p>
              </div>
            </div>
            <div className="mc-company-actions" id={`mc-company-actions-${company.id}`}>
              <button
                onClick={() => handleStartEdit(company)}
                id={`mc-edit-btn-${company.id}`}
                className="mc-btn mc-edit-btn"
              >
                ✏️ Redigera
              </button>
              <button
                onClick={() => openDeleteModal(company)}
                id={`mc-delete-btn-${company.id}`}
                className="mc-btn mc-delete-btn"
              >
                ❌
              </button>
            </div>
          </li>
        ))}
      </ul>

      {showAddModal && (
        <Modal onClose={() => setShowAddModal(false)}>
          <h2>Lägg till nytt företag</h2>
          <div className="mc-form-group">
            <label htmlFor="mc-add-name">Företagsnamn:</label>
            <input
              type="text"
              id="mc-add-name"
              className="mc-input"
              value={newCompanyName}
              onChange={(e) => setNewCompanyName(e.target.value)}
            />
          </div>
          <div className="mc-form-group">
            <label htmlFor="mc-add-address">Adress:</label>
            <input
              type="text"
              id="mc-add-address"
              className="mc-input"
              value={newCompanyAddress}
              onChange={(e) => setNewCompanyAddress(e.target.value)}
            />
          </div>
          <div className="mc-form-group">
            <label htmlFor="mc-add-phone">Telefon:</label>
            <input
              type="text"
              id="mc-add-phone"
              className="mc-input"
              value={newCompanyPhone}
              onChange={(e) => setNewCompanyPhone(e.target.value)}
            />
          </div>
          <div className="mc-form-group">
            <label htmlFor="mc-add-image">Bild URL:</label>
            <input
              type="text"
              id="mc-add-image"
              className="mc-input"
              value={newCompanyImageUrl}
              onChange={(e) => setNewCompanyImageUrl(e.target.value)}
            />
          </div>
          <div className="mc-form-group">
            <label htmlFor="mc-add-image-file">Välj bild:</label>
            <input
              type="file"
              id="mc-add-image-file"
              className="mc-input"
              accept="image/*"
              onChange={handleFileChange}
            />
          </div>
          <div className="mc-button-group">
            <button onClick={handleAddCompany} className="mc-btn">Spara</button>
            <button onClick={() => setShowAddModal(false)} className="mc-btn mc-cancel-btn">Avbryt</button>
          </div>
        </Modal>
      )}

      {showEditModal && (
        <Modal onClose={handleCancelEdit}>
          <h2>Redigera företag</h2>
          <div className="mc-form-group">
            <label htmlFor="mc-edit-id">Företags-ID:</label>
            <input
              type="text"
              id="mc-edit-id"
              className="mc-input"
              value={editCompanyId}
              onChange={(e) => setEditCompanyId(e.target.value)}
            />
          </div>
          <div className="mc-form-group">
            <label htmlFor="mc-edit-name">Företagsnamn:</label>
            <input
              type="text"
              id="mc-edit-name"
              className="mc-input"
              value={editCompanyName}
              onChange={(e) => setEditCompanyName(e.target.value)}
            />
          </div>
          <div className="mc-form-group">
            <label htmlFor="mc-edit-address">Adress:</label>
            <input
              type="text"
              id="mc-edit-address"
              className="mc-input"
              value={editCompanyAddress}
              onChange={(e) => setEditCompanyAddress(e.target.value)}
            />
          </div>
          <div className="mc-form-group">
            <label htmlFor="mc-edit-phone">Telefon:</label>
            <input
              type="text"
              id="mc-edit-phone"
              className="mc-input"
              value={editCompanyPhone}
              onChange={(e) => setEditCompanyPhone(e.target.value)}
            />
          </div>
          <div className="mc-form-group">
            <label htmlFor="mc-edit-image">Bild URL:</label>
            <input
              type="text"
              id="mc-edit-image"
              className="mc-input"
              value={editCompanyImageUrl}
              onChange={(e) => setEditCompanyImageUrl(e.target.value)}
            />
          </div>
          <div className="mc-button-group">
            <button onClick={handleSaveEditCompany} className="mc-btn">Spara ändringar</button>
            <button onClick={handleCancelEdit} className="mc-btn mc-cancel-btn">Avbryt</button>
          </div>
        </Modal>
      )}

      {showDeleteModal && (
        <Modal onClose={() => setShowDeleteModal(false)}>
          <h2>Bekräfta radering</h2>
          <p>
            Är du säker att du vill ta bort detta företag? ALL data (användare, publicerade jobb, pageVisits och ansökningar) med detta companyId kommer att tas bort.
          </p>
          <div className="mc-button-group">
            <button onClick={confirmDeleteCompany} className="mc-btn mc-delete-btn">Ja</button>
            <button onClick={() => setShowDeleteModal(false)} className="mc-btn mc-cancel-btn">Nej</button>
          </div>
        </Modal>
      )}
    </div>
  );
}

export default ManageCompanies;
