import React, { useState, useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import { collection, getDocs, query, where, doc, getDoc, addDoc } from 'firebase/firestore';
import { db } from './firebase';
import './JobLandingPage.css';
import { 
  FaUser, 
  FaEnvelope, 
  FaPhone, 
  FaFileAlt, 
  FaPaperclip, 
  FaBriefcase, 
  FaLocationArrow,
  FaCheckCircle,
  FaBuilding,
  FaMapMarkerAlt
} from 'react-icons/fa';

// Hjälpfunktion för att bestämma enhetstyp
function getDeviceType(userAgent) {
  if (/tablet|ipad|playbook|silk/i.test(userAgent)) {
    return "tablet";
  } else if (/Mobile|Android|iPhone|iPod/i.test(userAgent)) {
    return "phone";
  }
  return "desktop";
}

function JobLandingPage() {
  const { jobId } = useParams();
  const [job, setJob] = useState(null);
  const [company, setCompany] = useState(null);
  const [loading, setLoading] = useState(true);
  const formRef = useRef(null);
  const [cv, setCv] = useState(null);
  const [personalLetter, setPersonalLetter] = useState(null);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '' });
  const [errorMessage, setErrorMessage] = useState('');
  const [showPrivacyPolicy, setShowPrivacyPolicy] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  // Standardbild om inget företagsbild finns
  const defaultCompanyImageUrl = "https://via.placeholder.com/150";

  useEffect(() => {
    const fetchJobAndCompany = async () => {
      try {
        const jobsQuery = query(collection(db, 'jobs'), where('jobId', '==', jobId));
        const jobSnapshot = await getDocs(jobsQuery);
        if (!jobSnapshot.empty) {
          const jobData = jobSnapshot.docs[0].data();
          setJob(jobData);
          if (jobData.companyId) {
            try {
              const companyRef = doc(db, 'companies', jobData.companyId);
              const companySnap = await getDoc(companyRef);
              if (companySnap.exists()) {
                setCompany(companySnap.data());
              } else {
                setCompany({
                  name: jobData.companyName || "Okänt företag",
                  imageUrl: jobData.companyImageUrl || defaultCompanyImageUrl
                });
              }
            } catch (error) {
              console.error("Fel vid hämtning av företag:", error.message);
              setCompany({
                name: jobData.companyName || "Okänt företag",
                imageUrl: jobData.companyImageUrl || defaultCompanyImageUrl
              });
            }
          }
        }
      } catch (err) {
        console.error('Fel vid hämtning av jobb:', err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchJobAndCompany();
  }, [jobId]);

  // Logga besöket – nu sparas även deviceType
  useEffect(() => {
    if (job) {
      const logVisit = async () => {
        try {
          const deviceType = getDeviceType(navigator.userAgent);
          const docRef = await addDoc(collection(db, 'pageVisits'), {
            jobId: job.jobId,
            companyId: job.companyId,
            timestamp: new Date().toISOString(),
            referrer: document.referrer || 'direct',
            userAgent: navigator.userAgent,
            deviceType // sparar t.ex. "phone", "tablet" eller "desktop"
          });
          console.log("Besöksdokument skapat med ID:", docRef.id);
        } catch (error) {
          console.error("Fel vid loggning av besök:", error);
        }
      };
      logVisit();
    }
  }, [job]);

  const handleFileUpload = (event, setFile) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onloadend = () => {
        setFile({ name: file.name, data: reader.result });
      };
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.phone) {
      setErrorMessage('Fyll i alla obligatoriska fält.');
      return;
    }
    try {
      await addDoc(collection(db, 'applications'), {
        name: formData.name,
        name_lower: formData.name.toLowerCase(),
        email: formData.email,
        phone: formData.phone,
        jobTitle: job?.title || 'Okänt jobb',
        jobId: jobId,
        companyId: job?.companyId || 'Okänt företag',
        cv: cv ? cv : null,
        personalLetter: personalLetter ? personalLetter : null,
        date: new Date().toISOString(),
        referrer: document.referrer || 'direct',
        contacted: false,
        interview: false,
        disqualified: false,
        hired: false,
        opened: false
      });
      setSubmitted(true);
      setErrorMessage('');
      setFormData({ name: '', email: '', phone: '' });
      setCv(null);
      setPersonalLetter(null);
    } catch (error) {
      console.error('Fel vid skicka ansökan:', error);
      setErrorMessage('Kunde inte skicka ansökan.');
    }
  };

  const scrollToForm = () => {
    formRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <div className="job-landing-page">
      <div className="hero">
        {loading ? (
          <div className="loading-spinner"></div>
        ) : (
          <>
            {company?.imageUrl && (
              <img src={company.imageUrl} alt={company.name} className="company-banner" />
            )}
            <h1>{job?.title || "Jobb hittades inte"}</h1>
            {job?.location && (
              <div className="job-location">
                <FaLocationArrow className="location-icon" /> <span className="location-text">{job.location}</span>
              </div>
            )}
            <p className="published-by">Publicerat av {company?.name || "Okänt företag"}</p>
            <button className="apply-button" onClick={scrollToForm}>Ansök nu</button>
          </>
        )}
      </div>

      {!loading && job && (
        <>
          <div className="job-description">
            <FaBriefcase className="job-icon" />
            <div
              className="job-description-content"
              dangerouslySetInnerHTML={{ __html: job?.description || "Ingen beskrivning tillgänglig" }}
            />
          </div>

          <div className="application-form-container" ref={formRef}>
            {submitted ? (
              <div className="application-success">
                <FaCheckCircle className="success-icon" />
                <h2>Tack för din ansökan!</h2>
                <p>Du har nu skickat in din ansökan.</p>
              </div>
            ) : (
              <>
                <div className="application-header">
                  <div className="header-badge">
                    <FaCheckCircle className="badge-icon" /> Enkel och snabb ansökan
                  </div>
                  <h2 className="header-title">Ansök till jobbet!</h2>
                  <div className="header-details">
                    <div className="header-line">
                      <FaBriefcase className="header-icon" />
                      <span className="form-job-title">{job?.title}</span>
                    </div>
                    <div className="header-line">
                      <FaMapMarkerAlt className="header-icon" />
                      <span className="form-job-location">{job?.location}</span>
                    </div>
                    <div className="header-line">
                      <FaBuilding className="header-icon" />
                      <span className="form-company-name">{company?.name}</span>
                    </div>
                  </div>
                </div>
                <form className="application-form" onSubmit={handleSubmit}>
                  <div className="input-group">
                    <FaUser className="input-icon" />
                    <input
                      type="text"
                      name="name"
                      placeholder="Fullständigt namn *"
                      value={formData.name}
                      onChange={handleChange}
                      required
                    />
                  </div>
                  <div className="input-group">
                    <FaEnvelope className="input-icon" />
                    <input
                      type="email"
                      name="email"
                      placeholder="E-postadress *"
                      value={formData.email}
                      onChange={handleChange}
                      required
                    />
                  </div>
                  <div className="input-group">
                    <FaPhone className="input-icon" />
                    <input
                      type="tel"
                      name="phone"
                      placeholder="Telefonnummer *"
                      value={formData.phone}
                      onChange={handleChange}
                      required
                    />
                  </div>
                  <div className="input-group file-upload">
                    <FaPaperclip className="input-icon" />
                    <input 
                      type="file" 
                      accept=".pdf,.doc,.docx" 
                      onChange={(e) => handleFileUpload(e, setCv)} 
                    />
                    <label>
                      {cv 
                        ? cv.name 
                        : <>Bifoga CV <span className="optional-tag">(Valfritt)</span></>
                      }
                    </label>
                  </div>
                  <div className="input-group file-upload">
                    <FaFileAlt className="input-icon" />
                    <input 
                      type="file" 
                      accept=".pdf,.doc,.docx" 
                      onChange={(e) => handleFileUpload(e, setPersonalLetter)} 
                    />
                    <label>
                      {personalLetter 
                        ? personalLetter.name 
                        : <>Bifoga Personligt Brev <span className="optional-tag">(Valfritt)</span></>
                      }
                    </label>
                  </div>
                  <div className="privacy-policy-text">
                    <p>
                      När du skickar in ansökan godkänner du{' '}
                      <a href="#!" onClick={(e) => { e.preventDefault(); setShowPrivacyPolicy(true); }}>
                        Integritetspolicyn
                      </a>{' '}
                      samt att {company?.name || "företaget"} lagrar dina uppgifter för att hantera din ansökan.
                    </p>
                  </div>
                  <button type="submit" className="submit-button">Skicka ansökan</button>
                </form>
                {errorMessage && <p className="error-message">{errorMessage}</p>}
              </>
            )}
          </div>
        </>
      )}

      <footer className="footer">
        <p>Copyright - 2025 - Qwio Group AB</p>
      </footer>

      {showPrivacyPolicy && (
        <div className="popup-overlay" onClick={() => setShowPrivacyPolicy(false)}>
          <div className="popup" onClick={(e) => e.stopPropagation()}>
            <div className="popup-close" onClick={() => setShowPrivacyPolicy(false)}>X</div>
            <h2>Integritetspolicy</h2>
            <p>
              Vi på {company?.name || "företaget"} värnar om din integritet och behandlar dina personuppgifter med största respekt.
              När du skickar in din ansökan lagrar vi dina uppgifter för att kunna hantera rekryteringsprocessen på ett säkert och effektivt sätt.
              Dina personuppgifter kommer endast att användas för att utvärdera din ansökan samt för att kontakta dig angående en intervju eller annan information.
            </p>
            <p>
              Genom att skicka in din ansökan godkänner du att vi lagrar och behandlar dina personuppgifter enligt denna policy.
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

export default JobLandingPage;
