import React, { useState, useEffect, useCallback } from 'react';
import {
  collection,
  getDocs,
  query,
  where,
  doc,
  updateDoc,
  getDoc,
  deleteDoc,
  orderBy,
  limit,
  startAfter,
  onSnapshot
} from 'firebase/firestore';
import { db } from './firebase';
import { v4 as uuidv4 } from 'uuid';
import './JobApplications.css';
import {
  FaCheckCircle,
  FaStar,
  FaClock,
  FaBell,
  FaPhone,
  FaTimes,
  FaEdit,
  FaTrashAlt,
  FaSave,
  FaSearch,
  FaLocationArrow,
  FaArrowLeft
} from 'react-icons/fa';

function JobApplications({ user, refreshUnopenedCount }) {
  // --- State-variabler ---
  const [jobs, setJobs] = useState([]);
  const [applications, setApplications] = useState([]);
  const [selectedJob, setSelectedJob] = useState(null);
  const [selectedApplication, setSelectedApplication] = useState(null);
  const [comment, setComment] = useState('');
  const [ratings, setRatings] = useState({});
  const [filter, setFilter] = useState("inkorg");
  const [searchTerm, setSearchTerm] = useState('');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [editingCommentId, setEditingCommentId] = useState(null);
  const [editingCommentText, setEditingCommentText] = useState('');
  const [jobNotifications, setJobNotifications] = useState({});
  const [showDetails, setShowDetails] = useState(false);
  const [lastVisibleDoc, setLastVisibleDoc] = useState(null);
  const [hasMore, setHasMore] = useState(true);
  // Ny state för popup för filvisning (CV / personligt brev)
  const [filePopup, setFilePopup] = useState(null);

  // Nya state för laddningsindikatorer
  const [isLoadingJobs, setIsLoadingJobs] = useState(true);
  const [isLoadingApps, setIsLoadingApps] = useState(false);

  // Hjälpfunktion för "X dagar sedan"
  const formatTimeAgo = (dateStr) => {
    if (!dateStr) return "";
    const now = new Date();
    const inputDate = new Date(dateStr);
    const diffTime = now - inputDate;
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    if (diffDays === 0) return "Idag";
    if (diffDays === 1) return "Igår";
    if (diffDays < 7) return `${diffDays} dagar sedan`;
    if (diffDays < 30) {
      const weeks = Math.floor(diffDays / 7);
      return weeks === 1 ? "1 vecka sedan" : `${weeks} veckor sedan`;
    }
    const months = Math.floor(diffDays / 30);
    return months === 1 ? "1 månad sedan" : `${months} månader sedan`;
  };

  // Uppdaterad markDuplicates: För varje telefonnummer markeras den äldsta (minsta datumet) som inte en dublett.
  const markDuplicates = (apps) => {
    const grouped = {};
    apps.forEach(app => {
      if (!grouped[app.phone]) {
        grouped[app.phone] = [];
      }
      grouped[app.phone].push(app);
    });

    const markedApps = [];
    Object.keys(grouped).forEach(phone => {
      const group = grouped[phone];
      let earliestApp = group.reduce((prev, curr) =>
        prev.date < curr.date ? prev : curr
      );
      group.forEach(app => {
        if (app.id === earliestApp.id) {
          markedApps.push({ ...app, duplicate: false });
        } else {
          markedApps.push({ ...app, duplicate: true });
        }
      });
    });

    return markedApps.sort((a, b) => b.date.localeCompare(a.date));
  };

  // Hämta jobb för företaget
  useEffect(() => {
    const fetchJobs = async () => {
      setIsLoadingJobs(true);
      try {
        const q = query(collection(db, 'jobs'), where('companyId', '==', user.companyId));
        const jobsSnapshot = await getDocs(q);
        const jobsList = jobsSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        const filteredJobs = user.role === 'admin'
          ? jobsList
          : jobsList.filter(job => job.allowedMembers && job.allowedMembers.includes(user.uid));
        setJobs(filteredJobs);
      } catch (error) {
        console.error("❌ Fel vid hämtning av jobb:", error.message);
      } finally {
        setIsLoadingJobs(false);
      }
    };
    fetchJobs();
  }, [user.companyId, user.uid, user.role]);

  // Realtidslyssnare för oöppnade ansökningar
  useEffect(() => {
    if (user.companyId) {
      const notificationsQuery = query(
        collection(db, 'applications'),
        where('companyId', '==', user.companyId),
        where('opened', '==', false),
        where('contacted', '==', false),
        where('interview', '==', false),
        where('disqualified', '==', false),
        where('hired', '==', false)
      );
      const unsubscribe = onSnapshot(notificationsQuery, (snapshot) => {
        const notifications = {};
        snapshot.docs.forEach(doc => {
          const data = doc.data();
          const jobId = data.jobId;
          notifications[jobId] = true;
        });
        setJobNotifications(notifications);
      });
      return () => unsubscribe();
    }
  }, [user.companyId]);

  // ***********************
  // HÄMTNING AV ANSÖKNINGAR
  // ***********************

  const buildApplicationsQuery = useCallback((jobId, startAfterDoc = null) => {
    const qRef = collection(db, 'applications');
    const constraints = [ where('jobId', '==', jobId) ];
    
    if (searchTerm.trim() === '') {
      if (filter === "inkorg") {
        constraints.push(where('contacted', '==', false));
        constraints.push(where('interview', '==', false));
        constraints.push(where('disqualified', '==', false));
        constraints.push(where('hired', '==', false));
      } else if (filter === "contacted") {
        constraints.push(where('contacted', '==', true));
        constraints.push(where('interview', '==', false));
        constraints.push(where('disqualified', '==', false));
        constraints.push(where('hired', '==', false));
      } else if (filter === "interview") {
        constraints.push(where('interview', '==', true));
        constraints.push(where('disqualified', '==', false));
        constraints.push(where('hired', '==', false));
      } else if (filter === "disqualified") {
        constraints.push(where('disqualified', '==', true));
        constraints.push(where('hired', '==', false));
      } else if (filter === "anställa") {
        constraints.push(where('hired', '==', true));
      }
      constraints.push(orderBy('date', 'desc'));
    } else {
      const searchTermLower = searchTerm.toLowerCase();
      constraints.push(orderBy('name_lower'));
      constraints.push(where('name_lower', '>=', searchTermLower));
      constraints.push(where('name_lower', '<=', searchTermLower + '\uf8ff'));
    }
    
    if (startAfterDoc) {
      constraints.push(startAfter(startAfterDoc));
    }
    
    constraints.push(limit(12));
    
    return query(qRef, ...constraints);
  }, [filter, searchTerm]);

  const fetchApplications = useCallback(async (jobId) => {
    setIsLoadingApps(true);
    try {
      const q = buildApplicationsQuery(jobId, null);
      const snapshot = await getDocs(q);
      let apps = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      apps = markDuplicates(apps);
      
      const initialRatings = {};
      apps.forEach(app => {
        initialRatings[app.id] = app.rating || 0;
      });
      setRatings(initialRatings);
      setApplications(apps);
      setSelectedJob(jobId);
      
      if (snapshot.docs.length > 0) {
        setLastVisibleDoc(snapshot.docs[snapshot.docs.length - 1]);
        setHasMore(snapshot.docs.length === 12);
      } else {
        setLastVisibleDoc(null);
        setHasMore(false);
      }
    } catch (error) {
      console.error("❌ Fel vid hämtning av ansökningar:", error.message);
    } finally {
      setIsLoadingApps(false);
    }
  }, [buildApplicationsQuery]);

  const loadMoreApplications = async () => {
    try {
      if (!lastVisibleDoc) return;
      const q = buildApplicationsQuery(selectedJob, lastVisibleDoc);
      const snapshot = await getDocs(q);
      let newApps = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      newApps = markDuplicates(newApps);
      setApplications(prev => markDuplicates([...prev, ...newApps]));
      if (snapshot.docs.length > 0) {
        setLastVisibleDoc(snapshot.docs[snapshot.docs.length - 1]);
        setHasMore(snapshot.docs.length === 12);
      } else {
        setLastVisibleDoc(null);
        setHasMore(false);
      }
    } catch (error) {
      console.error("❌ Fel vid laddning av fler ansökningar:", error.message);
    }
  };

  useEffect(() => {
    if (selectedJob) {
      fetchApplications(selectedJob);
    }
  }, [filter, searchTerm, selectedJob, fetchApplications]);

  const addToActivityLog = async (appId, message) => {
    try {
      const appRef = doc(db, 'applications', appId);
      const appDoc = await getDoc(appRef);
      if (appDoc.exists()) {
        const data = appDoc.data();
        const oldLog = data.activityLog || [];
        const newEntry = {
          id: uuidv4(),
          userId: user.id || user.uid || 'anonymous',
          userName: user.name || 'Okänd användare',
          message: message,
          timestamp: new Date().toISOString(),
        };
        const updatedLog = [...oldLog, newEntry];
        await updateDoc(appRef, { activityLog: updatedLog });
      }
    } catch (err) {
      console.error("Kunde inte lägga till i activityLog:", err);
    }
  };

  const getCandidateFilter = (candidate) => {
    if (candidate.hired) return "anställa";
    if (candidate.disqualified) return "disqualified";
    if (candidate.interview) return "interview";
    if (candidate.contacted) return "contacted";
    return "inkorg";
  };

  const toggleStatus = async (statusType) => {
    if (selectedApplication) {
      const appRef = doc(db, 'applications', selectedApplication.id);
      const newStatus = !selectedApplication[statusType];
      await updateDoc(appRef, { [statusType]: newStatus });
      
      const updatedCandidate = { ...selectedApplication, [statusType]: newStatus };
      const candidateFilter = getCandidateFilter(updatedCandidate);
      
      if (candidateFilter !== filter) {
        setApplications(prevApps => prevApps.filter(app => app.id !== updatedCandidate.id));
      } else {
        setApplications(prevApps =>
          prevApps.map(app => app.id === updatedCandidate.id ? updatedCandidate : app)
        );
      }
      
      setSelectedApplication(updatedCandidate);
      if (typeof refreshUnopenedCount === 'function') {
        refreshUnopenedCount();
      }
      
      const statusName = { 
        contacted: 'Kontaktad', 
        interview: 'Bokad intervju', 
        disqualified: 'Ej kvalificerad', 
        hired: 'Anställd' 
      }[statusType] || statusType;
      const actionText = `${statusName}: ${newStatus ? 'checked' : 'unchecked'}`;
      await addToActivityLog(selectedApplication.id, actionText);
    }
  };

  const handleSelectApplication = async (app) => {
    if (!app.opened) {
      const appRef = doc(db, 'applications', app.id);
      await updateDoc(appRef, { opened: true });
      await addToActivityLog(app.id, `Ansökan öppnades av ${user.name || 'Okänd användare'}`);
      const updatedApp = { ...app, opened: true };
      setApplications(prevApps => prevApps.map(item => (item.id === app.id ? updatedApp : item)));
      if (typeof refreshUnopenedCount === 'function') {
        refreshUnopenedCount();
      }
    }
    const appRef = doc(db, 'applications', app.id);
    const appDoc = await getDoc(appRef);
    if (appDoc.exists()) {
      setSelectedApplication({ 
        ...app, 
        opened: true, 
        comments: appDoc.data().comments || [], 
        activityLog: appDoc.data().activityLog || [] 
      });
    } else {
      setSelectedApplication({ 
        ...app, 
        opened: true, 
        comments: [], 
        activityLog: [] 
      });
    }
  };

  const handleSaveComment = async () => {
    if (selectedApplication && selectedApplication.id && comment.trim() !== '') {
      const newComment = {
        id: uuidv4(),
        userId: user.id || user.uid || 'anonymous',
        userName: user.name || 'Okänd användare',
        text: comment,
        timestamp: new Date().toISOString()
      };
      const appRef = doc(db, 'applications', selectedApplication.id);
      const appDoc = await getDoc(appRef);
      const existingComments = appDoc.exists() && appDoc.data().comments ? appDoc.data().comments : [];
      const updatedComments = [...existingComments, newComment];
      await updateDoc(appRef, { comments: updatedComments });
      await addToActivityLog(selectedApplication.id, `Kommentar tillagd av ${user.name}`);
      setSelectedApplication({ ...selectedApplication, comments: updatedComments });
      setComment('');
    }
  };

  const handleRating = async (appId, newRating) => {
    const appRef = doc(db, 'applications', appId);
    await updateDoc(appRef, { rating: newRating });
    setRatings(prevRatings => ({ ...prevRatings, [appId]: newRating }));
    if (selectedApplication && selectedApplication.id === appId) {
      setSelectedApplication({ ...selectedApplication, rating: newRating });
    }
    await addToActivityLog(appId, `Betyg ändrades till ${newRating} av ${user.name}`);
  };

  const handleSaveEditedComment = async (commentId) => {
    if (!selectedApplication) return;
    const updatedComments = selectedApplication.comments.map((c) => {
      if (c.id === commentId) {
        return { ...c, text: editingCommentText };
      }
      return c;
    });
    const appRef = doc(db, 'applications', selectedApplication.id);
    await updateDoc(appRef, { comments: updatedComments });
    await addToActivityLog(selectedApplication.id, `En kommentar redigerades av ${user.name}`);
    setSelectedApplication({ ...selectedApplication, comments: updatedComments });
    setEditingCommentId(null);
    setEditingCommentText('');
  };

  const handleDeleteComment = async (commentId) => {
    if (!selectedApplication) return;
    const updatedComments = selectedApplication.comments.filter(c => c.id !== commentId);
    const appRef = doc(db, 'applications', selectedApplication.id);
    await updateDoc(appRef, { comments: updatedComments });
    await addToActivityLog(selectedApplication.id, `En kommentar raderades av ${user.name}`);
    setSelectedApplication({ ...selectedApplication, comments: updatedComments });
  };

  const handleFilterChange = (newFilter) => {
    setFilter(newFilter);
  };

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };

  // Funktion för att öppna fil-popup med inbäddat innehåll
  const openFilePopup = (file, fileType) => {
    setFilePopup({ ...file, type: fileType });
  };

  return (
    <div className="job-applications">
      {!selectedJob ? (
        isLoadingJobs ? (
          <div className="loading-spinner">
            <div className="spinner"></div>
          </div>
        ) : (
          <>
            <h2>Publicerade jobb</h2>
            <div className="job-grid">
              {jobs.map((job) => {
                const jobId = job.jobId || job.id;
                return (
                  <div key={job.id} className="job-card" style={{ position: 'relative' }}>
                    {jobNotifications[jobId] && (
                      <div className="notification-clock">
                        <FaBell className="notification-icon" style={{ fontSize: '20px', color: 'red' }} />
                        <span className="tooltip">Nya ansökningar</span>
                      </div>
                    )}
                    <h3>{job.title}</h3>
                    {job.location && (
                      <div className="job-location" style={{ justifyContent: 'center', display: 'flex', marginTop: '8px' }}>
                        <FaLocationArrow className="location-icon" style={{ marginRight: '5px' }} />
                        <span>{job.location}</span>
                      </div>
                    )}
                    <button onClick={() => fetchApplications(job.jobId || job.id)}>
                      Se ansökningar
                    </button>
                  </div>
                );
              })}
            </div>
          </>
        )
      ) : (
        isLoadingApps ? (
          <div className="loading-spinner">
            <div className="spinner"></div>
          </div>
        ) : (
          <>
            <button className="back-button" onClick={() => { setSelectedJob(null); setApplications([]); }}>
              <FaArrowLeft style={{ marginRight: '8px' }} />
              Tillbaka
            </button>
            <div className="filter-buttons">
              <button className={filter === "inkorg" ? "active" : ""} onClick={() => handleFilterChange("inkorg")}>
                Nya ansökningar
              </button>
              <button className={filter === "contacted" ? "active" : ""} onClick={() => handleFilterChange("contacted")}>
                Kontaktad
              </button>
              <button className={filter === "interview" ? "active" : ""} onClick={() => handleFilterChange("interview")}>
                Bokad intervju
              </button>
              <button className={filter === "disqualified" ? "active" : ""} onClick={() => handleFilterChange("disqualified")}>
                Ej kvalificerad
              </button>
              <button className={filter === "anställa" ? "active" : ""} onClick={() => handleFilterChange("anställa")}>
                Anställa
              </button>
            </div>
            <div className="search-container">
              <FaSearch className="search-icon" />
              <input 
                type="text"
                placeholder="Sök efter namn..."
                value={searchTerm}
                onChange={handleSearchChange}
              />
              {searchTerm && (
                <button 
                  className="clear-search-button" 
                  onClick={() => setSearchTerm('')}
                  title="Rensa sökning"
                >
                  <FaTimes />
                </button>
              )}
            </div>
            <h2>Ansökningar</h2>
            {jobs.length > 0 && (() => {
              const jobObj = jobs.find(job => (job.jobId || job.id) === selectedJob);
              return jobObj ? (
                <div className="job-details">
                  <h3>{jobObj.title}</h3>
                  {jobObj.location && (
                    <div className="job-location">
                      <FaLocationArrow className="location-icon" style={{ color: 'darkgrey' }} />
                      <span>{jobObj.location}</span>
                    </div>
                  )}
                </div>
              ) : null;
            })()}
            <div className="applications-grid">
              {applications.map((app) => (
                <div key={app.id} className="application-card">
                  {app.duplicate && (
                    <div className="duplicate-banner">
                      Dubblett
                    </div>
                  )}
                  {app.hired ? (
                    <div className="hired-banner">
                      Anställa <FaCheckCircle className="hired-icon" />
                    </div>
                  ) : app.disqualified ? (
                    <div className="disqualified-banner">
                      Ej kvalificerad <FaTimes className="disqualified-icon" />
                    </div>
                  ) : app.interview ? (
                    <div className="interview-banner">
                      Bokad intervju <FaCheckCircle className="interview-icon" />
                    </div>
                  ) : app.contacted ? (
                    <div className="contacted-banner">
                      Kontaktad <FaCheckCircle className="contacted-icon" />
                    </div>
                  ) : null}
                  <div className="avatar-container">
                    <div className="avatar-circle">
                      {app.name.split(' ').slice(0, 2).map(n => n[0]).join('').toUpperCase()}
                    </div>
                  </div>
                  <div className="application-info">
                    <h4 className="clickable-name" onClick={() => handleSelectApplication(app)}>
                      {app.name}
                    </h4>
                    {app.opened && (
                      <div className="opened-banner">
                        <FaCheckCircle className="check-icon" /> Öppnad
                      </div>
                    )}
                    <div className="rating">
                      {[1, 2, 3, 4, 5].map(star => (
                        <FaStar 
                          key={star} 
                          className={star <= (ratings[app.id] || 0) ? "star filled" : "star"} 
                          onClick={() => handleRating(app.id, star)} 
                        />
                      ))}
                    </div>
                  </div>
                  <div className="time-ago">
                    <FaClock className="clock-icon" /> {formatTimeAgo(app.date)}
                  </div>
                </div>
              ))}
            </div>
            {hasMore && (
              <button 
                className="load-more-button" 
                onClick={loadMoreApplications}
                style={{
                  backgroundColor: "#0084ff",
                  color: "#fff",
                  padding: "12px 24px",
                  fontSize: "16px",
                  border: "none",
                  borderRadius: "4px",
                  cursor: "pointer",
                  marginTop: "20px"
                }}
              >
                Ladda fler ansökningar
              </button>
            )}
          </>
        )
      )}

      {selectedApplication && (
        <div className="popup-overlay" onClick={() => setSelectedApplication(null)}>
          <div className="popup" onClick={(e) => e.stopPropagation()}>
            <div className="popup-close" onClick={() => setSelectedApplication(null)}>
              <FaTimes />
            </div>
            <div className="popup-rating">
              {[1, 2, 3, 4, 5].map(star => (
                <FaStar 
                  key={star} 
                  className={star <= (selectedApplication.rating || 0) ? "star filled" : "star"} 
                  onClick={() => handleRating(selectedApplication.id, star)}
                />
              ))}
            </div>
            <div className="popup-content">
              <div className="popup-toggles">
                <div className="toggle-item">
                  <span className="toggle-label">Kontaktad</span>
                  <label className="switch">
                    <input 
                      type="checkbox" 
                      checked={selectedApplication.contacted || false} 
                      onChange={() => toggleStatus("contacted")} 
                    />
                    <span className="slider"></span>
                  </label>
                </div>
                <div className="toggle-item">
                  <span className="toggle-label">Bokad intervju</span>
                  <label className="switch">
                    <input 
                      type="checkbox" 
                      checked={selectedApplication.interview || false} 
                      onChange={() => toggleStatus("interview")} 
                    />
                    <span className="slider"></span>
                  </label>
                </div>
                <div className="toggle-item">
                  <span className="toggle-label">Ej kvalificerad</span>
                  <label className="switch">
                    <input 
                      type="checkbox" 
                      checked={selectedApplication.disqualified || false} 
                      onChange={() => toggleStatus("disqualified")} 
                    />
                    <span className="slider"></span>
                  </label>
                </div>
                <div className="toggle-item">
                  <span className="toggle-label">Anställa</span>
                  <label className="switch">
                    <input 
                      type="checkbox" 
                      checked={selectedApplication.hired || false} 
                      onChange={() => toggleStatus("hired")} 
                    />
                    <span className="slider"></span>
                  </label>
                </div>
              </div>
              <h2>{selectedApplication.name}</h2>
              <p><strong>Email:</strong> {selectedApplication.email}</p>
              <p>
                <FaPhone style={{ marginRight: '5px' }} />
                <strong>Telefon:</strong> {selectedApplication.phone}
              </p>
              {selectedApplication.cv && selectedApplication.cv.data && (
                <p>
                  <button className="file-button" onClick={() => openFilePopup(selectedApplication.cv, 'CV')}>
                    Visa CV
                  </button>
                </p>
              )}
              {selectedApplication.personalLetter && selectedApplication.personalLetter.data && (
                <p>
                  <button className="file-button" onClick={() => openFilePopup(selectedApplication.personalLetter, 'Personligt Brev')}>
                    Visa personligt brev
                  </button>
                </p>
              )}
              <div className="comment-section">
                <h3>Kommentarer</h3>
                <div className="comments-list">
                  {selectedApplication.comments?.map((comment) => (
                    <div key={comment.id} className="comment">
                      {editingCommentId === comment.id ? (
                        <div className="editing-comment">
                          <textarea
                            value={editingCommentText}
                            onChange={(e) => setEditingCommentText(e.target.value)}
                            style={{ width: '100%', marginTop: '5px' }}
                          />
                          <div className="edit-actions">
                            <FaSave 
                              className="action-icon" 
                              onClick={() => handleSaveEditedComment(comment.id)} 
                              title="Spara" 
                            />
                            <FaTimes 
                              className="action-icon" 
                              onClick={() => setEditingCommentId(null)}
                              title="Avbryt" 
                            />
                          </div>
                        </div>
                      ) : (
                        <div className="comment-wrapper">
                          <div className="comment-content">
                            <strong>{comment.userName}:</strong> {comment.text}
                          </div>
                          {((user.id || user.uid) === comment.userId) && (
                            <div className="comment-actions">
                              <FaEdit 
                                className="action-icon" 
                                onClick={() => {
                                  setEditingCommentId(comment.id);
                                  setEditingCommentText(comment.text);
                                }} 
                                title="Redigera" 
                              />
                              <FaTrashAlt 
                                className="action-icon" 
                                onClick={() => handleDeleteComment(comment.id)} 
                                title="Ta bort" 
                              />
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
                <textarea 
                  value={comment} 
                  onChange={(e) => setComment(e.target.value)}
                  placeholder="Skriv en kommentar..."
                />
                <button onClick={handleSaveComment}>Spara kommentar</button>
              </div>
              <div className="action-buttons-row">
                <button className="details-button" onClick={() => setShowDetails(!showDetails)}>
                  {showDetails ? 'Dölj detaljer' : 'Detaljer'}
                </button>
                <button className="delete-application-button" onClick={() => setShowDeleteConfirm(true)}>
                  Ta bort ansökan
                </button>
              </div>
              {showDetails && (
                <div 
                  className="details-content"
                  style={{ marginTop: '20px', border: '1px solid #ddd', padding: '10px', borderRadius: '6px' }}
                >
                  <h4>Historik</h4>
                  {selectedApplication.activityLog && selectedApplication.activityLog.length > 0 ? (
                    selectedApplication.activityLog.map(entry => (
                      <div 
                        key={entry.id} 
                        style={{ background: '#f8f9fa', padding: '8px', margin: '5px 0', borderRadius: '4px' }}
                      >
                        <strong>{entry.userName}</strong> - {entry.message}
                        <br />
                        <small>{entry.timestamp ? entry.timestamp.split('T')[0] : ''}</small>
                      </div>
                    ))
                  ) : (
                    <p>Ingen historik tillgänglig.</p>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
      {showDeleteConfirm && (
        <div className="confirmation-overlay" onClick={() => setShowDeleteConfirm(false)}>
          <div className="confirmation-popup" onClick={(e) => e.stopPropagation()}>
            <p>Är du säker att du vill ta bort denna ansökan?</p>
            <div className="confirmation-buttons">
              <button className="confirm-button" onClick={async () => {
                try {
                  const appRef = doc(db, 'applications', selectedApplication.id);
                  await deleteDoc(appRef);
                  setApplications(prev => prev.filter(app => app.id !== selectedApplication.id));
                  setSelectedApplication(null);
                  setShowDeleteConfirm(false);
                } catch (error) {
                  console.error("Fel vid borttagning av ansökan:", error);
                }
              }}>
                Ja
              </button>
              <button className="cancel-button" onClick={() => setShowDeleteConfirm(false)}>
                Nej
              </button>
            </div>
          </div>
        </div>
      )}
      
      {/* Popup för filvisning – modifierad med 92% bredd, stängning vid klick utanför, kryss, och alternativt innehåll om fil inte är PDF */}
      {filePopup && (
        <div className="file-popup-overlay" onClick={() => setFilePopup(null)}>
          <div className="file-popup" onClick={(e) => e.stopPropagation()}>
            <div className="popup-close" onClick={() => setFilePopup(null)}>
              <FaTimes />
            </div>
            <h2>{filePopup.type}</h2>
            {filePopup.name && filePopup.name.toLowerCase().endsWith('.pdf') ? (
              <iframe 
                src={filePopup.data} 
                title={filePopup.name || filePopup.type} 
                style={{ width: '100%', height: '80vh' }}
                frameBorder="0"
              />
            ) : (
              <div className="no-preview">
                <p>Ingen förhandgranskning på fil går att generera, du måste ladda ner denna fil lokalt.</p>
                <a href={filePopup.data} download={filePopup.name || "fil"} className="download-button">Ladda ner fil</a>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default JobApplications;
